    M1 = solve(L[:42,:],M[p[:42],42:])
    M2 = M[p[42:],42:]-L[42:,:]@M1

    Q,R,p = qr(M2[:,:-6],mode='economic',pivoting=True)
    A = solve(U,np.hstack([M1[:,p],M1[:,-6:]]))
    B = solve(R[:,:37],np.hstack([R[:,37:],Q.T@M2[:,-6:]]))
    M = np.vstack([-A[:,-33:]+A[:,:-33]@B,-B])

    P1 = np.hstack([np.arange(70,112),p,np.arange(64,70)])
    P2 = np.array([70,71,72,31,32,34,73,74,75,37,38,40,76,77,43,78,79,46,80,81,82,83,84,85,50,51,52,53,54,55,86,87,88,56,57,58,89,90,91,59,60,61,92,93,62,94,95,63,96,97,98,99,100,64,65,66,101,102,67,103,104,68,105,106,107,108,69,109,110,111])
    T = getT(M,P1[:-33],P1[-33:],P2)

    _,V = eig(T)
    S = V[27:32,:]/V[32,:]
    S = S[:,np.all(np.isfinite(S),axis=0)]

    return S